        title = "Reported speech",
        lesson = "Russian keeps the original tense in reported speech (no backshift). Use что for statements, ли for yes/no questions, and the original question word otherwise.",
        exampleRu = "Он сказа́л, что рабо́тает. Я спроси́л, придёт ли он.",
        exampleEn = "He said (that) he works. I asked whether he would come.",
