        exampleEn = "Despite the fact that it was hard, he made it in time.",
        hint = "однако / поэтому / несмотря на то что / в то время как.",
        order = 300,
        spine = false,
        cefrLevel = "C1",
        prerequisites = listOf(),
        interferesWith = listOf(),
        family = "COMPLEX",
        stage = 1
    )

    val NOMINALIZATION = GrammarConcept(
