    val DISCOURSE_PARTICLES = GrammarConcept(
        id = "DISCOURSE_PARTICLES",
        title = "Hedging and reported stance",
        lesson = "Near-native Russian marks the speaker's distance from a quoted claim with reporting particles: мол and де́скать flag casual reported speech (\\), я́кобы signals the claim may be false (\\), and вро́де бы softens a statement (\\). None of these change the sentence's grammar — they only signal the speaker's stance toward it.",
